// DTO types are generated by tauri-specta (src/lib/infrastructure/tauri/bindings.ts) and re-exported here.
// Type-only re-export: core never imports runtime code from infrastructure.
export type {
  Appearance,
  CommandError,
  Compatibility,
  DefaultStatus,
  ErrorCode,
  InstallEvent,
  InstallOutcome,
  InstallPhase,
  InstallScope,
  InstalledApp,
  PackageFormat,
  PackagePreview,
  UninstallOutcome
} from '../../infrastructure/tauri/bindings';

import type { CommandError, ErrorCode } from '../../infrastructure/tauri/bindings';

export const ERROR_CODES = [
  'permissionDenied',
  'offline',
  'missingDependencies',
  'conflicts',
  'notEnoughSpace',
  'corruptFile',
  'untrustedSource',
  'backendUnavailable',
  'notFound',
  'busy',
  'unknown'
] as const satisfies readonly ErrorCode[];

/** The `plan` InstallEvent minus its tag. */
export interface Plan {
  extraPackages: number;
  downloadBytes: number;
}

/** Normalise anything a gateway call may reject with into a CommandError. */
export function toCommandError(e: unknown): CommandError {
  if (typeof e === 'object' && e !== null && 'code' in e) {
    const { code, detail } = e as { code: unknown; detail?: unknown };
    if (typeof code === 'string' && (ERROR_CODES as readonly string[]).includes(code)) {
      return { code: code as ErrorCode, detail: typeof detail === 'string' ? detail : null };
    }
  }
  return {
    code: 'unknown',
    detail: e instanceof Error ? e.message : typeof e === 'string' ? e : null
  };
}
